import { Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import {
  TablerIconComponent, IconChevronRight, IconChevronDown, IconSettings, IconArrowsMaximize,
  IconBell, IconBuilding, IconLayoutSidebarLeftCollapse, IconLayoutSidebarLeftExpand,
  IconPlus, IconDownload, IconSend, IconPencil, IconTrash, IconRefresh,
  IconArrowBackUp, IconCheck, IconX, IconCalendarStats,
} from '@tabler/icons-angular';
import {
  HrmAppShell, HrmSideNav, HrmButton, HrmSegmented, HrmInput, HrmSelect, HrmTextarea,
  HrmDataView, HrmGridColumn, HrmBoardGroup, HrmStatusCell, HrmTag, HrmActionCell, HrmActionItem,
  HrmListPage, HrmDetailPeek, HrmPeekMode, HrmActionBar, HrmActionBarItem, HrmOption,
} from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont } from '../../../doc/sg-blocks';
import { SgRequestDetail } from './sg-request-detail';
import { DEFAULT_NAV_SECTIONS } from './_template-nav';
import { requestRows, REQ_TYPES, ReqRow, ReqStatus, ReqTypeKey, reqStatusMeta } from './_requests';

/** Doc page · Chế độ xem dữ liệu — ĐĂNG KÝ (Template) — biến thể "người tạo đơn": danh sách đơn
 *  từ CỦA TÔI (đa chế độ Bảng/Thẻ/Kanban theo trạng thái) + nút Tạo đơn + form nhập + theo dõi
 *  vòng đời (Nháp → Chờ duyệt → Đã duyệt/Từ chối). Hành động theo trạng thái: Gửi duyệt, Thu hồi,
 *  Đăng ký lại, Sửa. Self-contained, design token, tái dùng workflow chuẩn DS. */
@Component({
  selector: 'sg-template-request-register',
  imports: [
    NgTemplateOutlet, FormsModule, TablerIconComponent,
    HrmAppShell, HrmSideNav, HrmButton, HrmSegmented, HrmInput, HrmSelect, HrmTextarea,
    HrmDataView, HrmStatusCell, HrmTag, HrmActionCell, HrmListPage, HrmDetailPeek, HrmActionBar,
    SgRequestDetail, SgDoc, SgUse, SgDo, SgDont,
  ],
  template: `
    @if (preview) {
      <div class="lp-desktop lp-desktop--full"><ng-container *ngTemplateOutlet="screen" /></div>
    } @else {
    <sg-doc category="Template" title="Chế độ xem dữ liệu — Đăng ký"
      desc="Biến thể 'người tạo' của template danh sách: đăng ký & theo dõi đơn từ của tôi qua đa chế độ (Bảng/Thẻ/Kanban theo trạng thái). Tạo đơn, gửi duyệt, thu hồi, đăng ký lại — vòng đời Nháp → Chờ duyệt → Đã duyệt/Từ chối.">
      <div sgOverview>
        <div class="lp-desktop"><ng-container *ngTemplateOutlet="screen" /></div>
        <div class="lp-full">
          <a class="lp-full-link" href="/preview/request-register" target="_blank" rel="noopener">
            <hrm-button variant="default"><tabler-icon [icon]="maximize" [size]="16" /> Mở toàn màn hình</hrm-button>
          </a>
        </div>
      </div>
      <div sgUsage>
        <sg-use purpose="Cho NGƯỜI DÙNG tự đăng ký & theo dõi bản ghi của mình (đơn từ, đề xuất…): tạo mới, gửi duyệt, xem trạng thái xử lý."
          [when]="when"
          behavior="Danh sách của tôi + nút Tạo đơn; mỗi đơn có trạng thái vòng đời; hành động đổi theo trạng thái (Nháp: Gửi duyệt/Sửa/Xoá · Chờ duyệt: Thu hồi · Từ chối: Đăng ký lại)."
          avoid="Không dùng cho người DUYỆT (dùng biến thể Phê duyệt); không dùng cho danh mục tĩnh không có vòng đời." />
      </div>
      <div sgBest>
        <sg-do>Hiện rõ trạng thái vòng đời + hành động hợp lệ theo từng trạng thái.</sg-do>
        <sg-do>Kanban theo trạng thái để người dùng thấy đơn đang “kẹt” ở bước nào.</sg-do>
        <sg-dont>Đừng hiện nút Duyệt/Từ chối ở đây — đó là vai trò người phê duyệt.</sg-dont>
      </div>
    </sg-doc>
    }

    <ng-template #screen>
      <hrm-app-shell contentPad="none">
        <hrm-side-nav appSideNav [sections]="navSections" selectedKey="requests"
          [caretIcon]="caret" [logoSrc]="logo" [logoMarkSrc]="logoMark"
          [toggleIcon]="sbCollapse" [expandIcon]="sbExpand" [(collapsed)]="collapsedModel"
          [user]="navUser" [switchIcon]="gear" switchLabel="Cài đặt">
          <button snActions type="button" class="as-ico" aria-label="Thông báo"><tabler-icon [icon]="bell" [size]="20" /></button>
          <button snHead type="button" class="sn-acct" [class.sn-acct--mini]="collapsed()">
            <span class="sn-acct-ic"><tabler-icon [icon]="building" [size]="18" /></span>
            @if (!collapsed()) {
              <span class="sn-acct-info">
                <span class="sn-acct-name">Tập đoàn VNR</span>
                <span class="sn-acct-sub">Tài khoản doanh nghiệp</span>
              </span>
              <tabler-icon [icon]="chevDown" [size]="16" style="color:var(--text-soft)" />
            }
          </button>
        </hrm-side-nav>

        <hrm-list-page title="Đơn từ của tôi" [subtitle]="subtitle()"
          [total]="mode() === 'table' ? filteredRows().length : 0" [(pageIndex)]="page" [pageSize]="10" [panel]="mode() === 'table'">

          <div headerActions class="lp-hdr">
            <hrm-segmented [options]="viewSegments" [(ngModel)]="modeModel" size="md" />
            <hrm-button variant="primary" (click)="openCreate()"><tabler-icon [icon]="plus" [size]="18" /> Tạo đơn</hrm-button>
          </div>

          <div filters class="tbx">
            @if (selKeys().length === 0) {
              <hrm-input [(ngModel)]="kwModel" placeholder="Tìm mã đơn, loại…" style="width:240px" />
              <hrm-select [options]="statusFilterOptions" [(ngModel)]="statusFilterModel" style="width:170px" />
            } @else {
              <button type="button" class="bx-clear" aria-label="Bỏ chọn" (click)="selKeys.set([])"><tabler-icon [icon]="close" [size]="16" /></button>
              <span class="bx-count">Đã chọn <b>{{ selKeys().length }}</b> đơn</span>
            }
          </div>
          <div actions class="tbx">
            @if (selKeys().length === 0) {
              <hrm-button variant="default"><tabler-icon [icon]="download" [size]="18" /> Xuất</hrm-button>
            } @else {
              <hrm-button variant="primary" (click)="bulkSubmit()"><tabler-icon [icon]="send" [size]="16" /> Gửi duyệt</hrm-button>
              <hrm-button variant="default" [danger]="true" (click)="bulkDelete()"><tabler-icon [icon]="trash" [size]="16" /> Xoá</hrm-button>
            }
          </div>

          <hrm-data-view
            [columns]="cols()" [data]="filteredRows()" rowKey="id" tableMinWidth="760px"
            [selectable]="true" [selectedKeys]="selKeys()" (selectedKeysChange)="selKeys.set($event)"
            [modes]="['table','card','kanban','gantt']" [mode]="mode()" (modeChange)="mode.set($any($event))"
            groupBy="status" [boardGroups]="boardGroups" boardAddLabel="Tạo đơn" (boardAdd)="openCreate()"
            startField="start" endField="end" ganttLabelField="code" ganttHeader="Đơn từ" ganttDateHeader="Thời gian"
            [ganttLabelTemplate]="gtLabel" [ganttBarTone]="ganttTone"
            [cardTemplate]="dvCard" [boardCardTemplate]="dvCard"
            (openRecord)="openDetail($any($event))"
            tableLabel="Bảng" cardLabel="Thẻ" kanbanLabel="Kanban" ganttLabel="Gantt" />

          <hrm-detail-peek lpDetail [(open)]="peekOpen" [(peekMode)]="peekMode"
            [modes]="['master','side','center','full','tab']" [expandable]="false"
            [title]="peekTitle()" [content]="peekContent()" [footer]="peekKind() === 'detail' ? peekFooter : null"
            [modeLabels]="peekLabels" [routeUrl]="peekRoute()"
            switchLabel="Đổi cách hiển thị" expandLabel="Mở toàn trang" closeLabel="Đóng" resizeLabel="Kéo đổi độ rộng" />
          <span pagerInfo>Hiển thị {{ filteredRows().length }} đơn</span>
        </hrm-list-page>
      </hrm-app-shell>
    </ng-template>

    <!-- CHI TIẾT đơn (peek) -->
    <ng-template #reqDetail>
      @if (selectedRow(); as r) { <sg-request-detail [req]="r" /> }
    </ng-template>

    <!-- FOOTER chi tiết — hành động theo trạng thái (người tạo đơn). -->
    <ng-template #peekFooter>
      @if (selectedRow(); as r) {
        <hrm-action-bar [actions]="regActions(r.status)" moreLabel="Thêm" (action)="applyReg(r, $event)" />
      }
    </ng-template>

    <!-- FORM tạo đơn (peek) -->
    <ng-template #reqForm>
      <form class="rf" (ngSubmit)="saveForm()">
        <div class="rf-body">
          <label class="rf-field"><span class="rf-lbl">Loại đơn <b class="rf-req">*</b></span>
            <hrm-select name="type" [(ngModel)]="form.type" [options]="typeOptions" placeholder="Chọn loại đơn" /></label>
          <div class="rf-row">
            <label class="rf-field"><span class="rf-lbl">Từ ngày</span><hrm-input name="from" [(ngModel)]="form.from" placeholder="dd/mm/yyyy" /></label>
            <label class="rf-field"><span class="rf-lbl">Đến ngày</span><hrm-input name="to" [(ngModel)]="form.to" placeholder="dd/mm/yyyy" /></label>
          </div>
          <label class="rf-field"><span class="rf-lbl">Người duyệt</span>
            <hrm-select name="approver" [(ngModel)]="form.approver" [options]="approverOptions" placeholder="Chọn người duyệt" /></label>
          <label class="rf-field"><span class="rf-lbl">Lý do</span>
            <hrm-textarea name="reason" [(ngModel)]="form.reason" [rows]="3" placeholder="Nhập lý do…" /></label>
        </div>
        <div class="rf-foot">
          <hrm-button type="button" variant="default" (click)="peekOpen.set(false)">Hủy</hrm-button>
          <hrm-button type="button" (click)="saveDraft()"><tabler-icon [icon]="pencil" [size]="16" /> Lưu nháp</hrm-button>
          <hrm-button type="submit" variant="primary"><tabler-icon [icon]="send" [size]="16" /> Gửi duyệt</hrm-button>
        </div>
      </form>
    </ng-template>

    <!-- Cells -->
    <ng-template #codeCell let-r><span class="c-code">{{ r.code }}</span></ng-template>
    <ng-template #typeCell let-r><hrm-tag color="blue">{{ REQ_TYPES[r.type] }}</hrm-tag></ng-template>
    <ng-template #timeCell let-r><span class="c-mut">{{ r.from }} → {{ r.to }}</span></ng-template>
    <ng-template #daysCell let-r><span>{{ r.days }} {{ r.unit }}</span></ng-template>
    <ng-template #apprCell let-r><span class="c-mut">{{ r.approver }}</span></ng-template>
    <ng-template #statusCell let-r>
      <hrm-status [status]="meta(r.status).tone" [label]="meta(r.status).vi" variant="badge" [dot]="true" />
    </ng-template>
    <!-- Cột hành động — GIỐNG template "Chế độ xem dữ liệu" (list-page): hrm-action-cell PHẲNG (không viền),
         icon xám lúc nghỉ, HOVER ra màu (Sửa→primary · Xoá→đỏ). Solid màu CHỈ dùng cho màn quyết định (Phê duyệt). -->
    <ng-template #actionCell let-r>
      <hrm-action-cell [actions]="rowActions" moreLabel="Thêm" (action)="onRowAction($event, r)" />
    </ng-template>

    <!-- Thẻ (card + kanban) -->
    <ng-template #dvCard let-r>
      <div class="rc">
        <div class="rc-top">
          <span class="c-code">{{ r.code }}</span>
          <hrm-status [status]="meta(r.status).tone" [label]="meta(r.status).vi" variant="badge" [dot]="true" />
        </div>
        <div class="rc-type"><hrm-tag color="blue">{{ REQ_TYPES[r.type] }}</hrm-tag></div>
        <div class="rc-meta">
          <div class="rc-row"><tabler-icon [icon]="icCal" [size]="14" /><span>{{ r.from }} → {{ r.to }} · {{ r.days }} {{ r.unit }}</span></div>
          <div class="rc-row"><tabler-icon [icon]="icAppr" [size]="14" /><span>{{ r.approver }}</span></div>
        </div>
      </div>
    </ng-template>

    <!-- Nhãn trái Gantt — mã đơn + loại (1 dòng, không xuống hàng). -->
    <ng-template #gtLabel let-r>
      <span class="gl"><span class="c-code">{{ r.code }}</span><span class="gl-type">{{ REQ_TYPES[r.type] }}</span></span>
    </ng-template>
  `,
  styles: [`
    .lp-desktop { height: 760px; border: 1px solid var(--border-sub); border-radius: var(--radius-xl); overflow: hidden; box-shadow: var(--shadow-regular-sm); }
    .lp-desktop--full { height: 100vh; border: 0; border-radius: 0; box-shadow: none; }
    .lp-full { margin-top: 14px; } .lp-full-link { text-decoration: none; }
    .lp-desktop ::ng-deep .shell-content { padding: 0; display: flex; flex-direction: column; min-height: 0; }
    .lp-desktop ::ng-deep .shell-content hrm-list-page { flex: 1 1 auto; min-height: 0; }
    .lp-desktop ::ng-deep hrm-data-view .dv-bar { display: none; }
    .lp-desktop ::ng-deep .ant-table-tbody > tr > td, .lp-desktop ::ng-deep .ant-table-thead > tr > th { white-space: nowrap; }
    :host ::ng-deep .ant-tag { margin: 0; }

    .lp-hdr { display: flex; align-items: center; justify-content: flex-end; gap: var(--space-8); }
    .tbx { display: flex; align-items: center; gap: var(--space-8); min-width: 0; }
    .bx-clear { display: grid; place-items: center; width: 28px; height: 28px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .bx-clear:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    .bx-count { font-size: var(--fs-13); color: var(--text-body); background: var(--primary-bg-subtle); padding: 4px 10px; border-radius: var(--radius-full); white-space: nowrap; }
    .bx-count b { color: var(--primary-base); }

    .c-code { font-family: var(--font-mono, ui-monospace, monospace); font-size: var(--fs-13); color: var(--text-strong); font-weight: var(--font-medium, 500); }
    .c-mut { font-size: var(--fs-13); color: var(--text-sub); }
    .gl { display: inline-flex; align-items: baseline; gap: var(--space-2, 8px); min-width: 0; white-space: nowrap; }
    .gl .c-code { flex: none; }
    .gl-type { font-size: var(--fs-12); color: var(--text-soft); overflow: hidden; text-overflow: ellipsis; }

    .rc { display: flex; flex-direction: column; gap: var(--space-2, 8px); }
    .rc-top { display: flex; align-items: center; justify-content: space-between; gap: var(--space-8); }
    .rc-type { display: flex; }
    .rc-meta { display: flex; flex-direction: column; gap: var(--space-1, 4px); }
    .rc-row { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .rc-row tabler-icon { flex: none; color: var(--text-soft); }
    .rc-row span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

    ::ng-deep .ant-drawer-body:has(.rf), ::ng-deep .ant-modal-body:has(.rf), ::ng-deep .dp-mbody:has(.rf) { padding: 0 !important; }
    .rf { display: flex; flex-direction: column; min-height: 100%; }
    .rf-body { flex: 1 1 auto; display: flex; flex-direction: column; gap: var(--space-4, 16px); padding: var(--space-5, 20px); }
    .rf-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-3, 12px); }
    .rf-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
    .rf-lbl { font-size: var(--fs-13); font-weight: var(--font-medium, 500); color: var(--text-body); }
    .rf-req { color: var(--error-base); }
    .rf-foot { position: sticky; bottom: 0; display: flex; justify-content: flex-end; gap: var(--space-2, 8px); padding: var(--space-4, 16px) var(--space-5, 20px) var(--space-5, 20px); background: var(--bg-surface); border-top: 1px solid var(--border-sub); }

    .as-ico { display: grid; place-items: center; width: 34px; height: 34px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .sn-acct { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); cursor: pointer; text-align: left; }
    .sn-acct--mini { width: auto; padding: 4px; border-color: transparent; background: transparent; }
    .sn-acct-ic { display: grid; place-items: center; width: 32px; height: 32px; border-radius: var(--radius-md); background: var(--primary-bg-subtle); color: var(--primary-base); flex: none; }
    .sn-acct-info { flex: 1; min-width: 0; }
    .sn-acct-name { display: block; font-size: var(--fs-14); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .sn-acct-sub { display: block; font-size: var(--fs-12); color: var(--text-sub); }
  `],
})
export class SgTemplateRequestRegister {
  protected readonly preview = inject(ActivatedRoute).snapshot.data['preview'] === true;
  protected readonly REQ_TYPES = REQ_TYPES;
  protected meta(s: ReqStatus) { return reqStatusMeta(s); }

  // chrome icons
  protected readonly caret = IconChevronRight;
  protected readonly maximize = IconArrowsMaximize;
  protected readonly chevDown = IconChevronDown;
  protected readonly bell = IconBell;
  protected readonly building = IconBuilding;
  protected readonly sbCollapse = IconLayoutSidebarLeftCollapse;
  protected readonly sbExpand = IconLayoutSidebarLeftExpand;
  protected readonly plus = IconPlus;
  protected readonly download = IconDownload;
  protected readonly send = IconSend;
  protected readonly pencil = IconPencil;
  protected readonly trash = IconTrash;
  protected readonly close = IconX;
  protected readonly icCal = IconCalendarStats;
  protected readonly icAppr = IconCheck;
  protected readonly logo = '/assets/vnr-logo-full.svg';
  protected readonly logoMark = '/assets/vnr-logo-mark.svg';
  protected readonly collapsed = signal(false);
  protected get collapsedModel(): boolean { return this.collapsed(); }
  protected set collapsedModel(v: boolean) { this.collapsed.set(v); }
  protected readonly navUser = { name: 'Đặng Anh', email: 'danganh@vnr.vn' };
  protected readonly gear = IconSettings;
  protected readonly when = ['Đơn từ / đề xuất tự phục vụ', 'Người dùng tạo & theo dõi bản ghi của mình', 'Vòng đời có duyệt nhiều bước'];

  protected readonly navSections = DEFAULT_NAV_SECTIONS;

  // ── state ──
  protected readonly rows = signal<ReqRow[]>(requestRows());
  protected readonly mode = signal<'table' | 'card' | 'kanban' | 'gantt'>('table');
  protected get modeModel() { return this.mode(); }
  protected set modeModel(v: string) { this.mode.set(v as 'table' | 'card' | 'kanban' | 'gantt'); }
  protected page = 1;

  private readonly _kw = signal('');
  protected get kwModel() { return this._kw(); }
  protected set kwModel(v: string) { this._kw.set(v); }
  private readonly _sf = signal<'all' | ReqStatus>('all');
  protected get statusFilterModel() { return this._sf(); }
  protected set statusFilterModel(v: string) { this._sf.set(v as 'all' | ReqStatus); }
  protected readonly statusFilterOptions: HrmOption[] = [
    { value: 'all', label: 'Tất cả trạng thái' },
    { value: 'draft', label: 'Nháp' },
    { value: 'pending', label: 'Chờ duyệt' },
    { value: 'approved', label: 'Đã duyệt' },
    { value: 'rejected', label: 'Đã từ chối' },
    { value: 'changeRequested', label: 'Yêu cầu thay đổi' },
  ];

  protected readonly filteredRows = computed<ReqRow[]>(() => {
    const kw = this._kw().trim().toLowerCase();
    const sf = this._sf();
    return this.rows().filter((r) => {
      if (sf !== 'all' && r.status !== sf) return false;
      if (kw && !`${r.code} ${REQ_TYPES[r.type]} ${r.reason}`.toLowerCase().includes(kw)) return false;
      return true;
    });
  });

  protected readonly subtitle = computed(() => {
    const n = this.rows().filter((r) => r.status === 'draft').length;
    const p = this.rows().filter((r) => r.status === 'pending').length;
    return `${n} nháp · ${p} chờ duyệt`;
  });

  protected readonly viewSegments = [
    { label: 'Bảng', value: 'table' }, { label: 'Thẻ', value: 'card' }, { label: 'Kanban', value: 'kanban' }, { label: 'Gantt', value: 'gantt' },
  ];
  /** Tông màu thanh Gantt theo trạng thái đơn (đồng bộ status). */
  protected readonly ganttTone = (r: Record<string, unknown>): string => reqStatusMeta(r['status'] as ReqStatus).tone;
  protected readonly boardGroups: HrmBoardGroup[] = [
    { key: 'draft', label: 'Nháp', tone: 'neutral' },
    { key: 'pending', label: 'Chờ duyệt', tone: 'warning' },
    { key: 'changeRequested', label: 'Yêu cầu thay đổi', tone: 'info' },
    { key: 'approved', label: 'Đã duyệt', tone: 'success' },
    { key: 'rejected', label: 'Đã từ chối', tone: 'error' },
  ];

  protected readonly rowActions: HrmActionItem[] = [
    { key: 'edit', icon: IconPencil, label: 'Sửa' },
    { key: 'delete', icon: IconTrash, label: 'Xoá', danger: true },
  ];
  protected onRowAction(key: string, r: ReqRow): void {
    if (key === 'edit') this.openEdit(r);
    else if (key === 'delete') this.rows.update((l) => l.filter((x) => x.id !== r.id));
  }

  // ── bulk ──
  protected readonly selKeys = signal<unknown[]>([]);
  protected bulkSubmit(): void {
    const ids = new Set(this.selKeys().map(Number));
    this.rows.update((l) => l.map((r) => (ids.has(r.id) && r.status === 'draft' ? { ...r, status: 'pending' as ReqStatus } : r)));
    this.selKeys.set([]);
  }
  protected bulkDelete(): void {
    const ids = new Set(this.selKeys().map(Number));
    this.rows.update((l) => l.filter((r) => !ids.has(r.id)));
    this.selKeys.set([]);
  }

  // ── peek ──
  protected readonly peekOpen = signal(false);
  protected readonly peekMode = signal<HrmPeekMode>('master');
  protected readonly peekKind = signal<'detail' | 'form'>('detail');
  protected readonly peekLabels: Partial<Record<HrmPeekMode, string>> = {
    master: 'Bảng + chi tiết', side: 'Cạnh danh sách', center: 'Giữa màn hình',
    full: 'Toàn trang', tab: 'Tab mới',
  };
  /** Đích Toàn trang (điều hướng) / Tab mới (window.open) — trang bản ghi độc lập. */
  protected readonly peekRoute = computed(() => {
    if (this.peekKind() === 'form') return '/styleguide/hrm/template/request-register';
    const id = this.selectedId();
    return id == null ? '' : `/styleguide/hrm/template/request-record?id=${id}&kind=register`;
  });
  protected readonly selectedId = signal<number | null>(null);
  protected readonly selectedRow = computed<ReqRow | null>(() => {
    const id = this.selectedId();
    return id == null ? null : this.rows().find((r) => r.id === id) ?? null;
  });
  private readonly reqDetailTpl = viewChild<TemplateRef<any>>('reqDetail');
  private readonly reqFormTpl = viewChild<TemplateRef<any>>('reqForm');
  protected readonly peekContent = computed<TemplateRef<unknown> | null>(() =>
    this.peekKind() === 'form' ? (this.reqFormTpl() ?? null) : (this.reqDetailTpl() ?? null));
  protected readonly peekTitle = computed(() => {
    if (this.peekKind() === 'form') return this.formMode() === 'create' ? 'Tạo đơn mới' : 'Sửa đơn';
    return this.selectedRow()?.code ?? '';
  });
  protected openDetail(r: ReqRow): void { this.selectedId.set(r.id); this.peekKind.set('detail'); this.peekOpen.set(true); }

  // ── status transitions (người tạo) ──
  private setStatus(id: number, s: ReqStatus): void {
    this.rows.update((l) => l.map((r) => (r.id === id ? { ...r, status: s } : r)));
  }
  /** Hành động hợp lệ theo trạng thái (góc nhìn người tạo đơn). */
  protected regActions(s: ReqStatus): HrmActionBarItem[] {
    switch (s) {
      case 'draft': return [
        { key: 'submit', label: 'Gửi duyệt', tone: 'primary', icon: IconSend },
        { key: 'edit', label: 'Sửa', tone: 'neutral', icon: IconPencil },
        { key: 'delete', label: 'Xoá', tone: 'error', icon: IconTrash },
      ];
      case 'pending': return [{ key: 'withdraw', label: 'Thu hồi', tone: 'warning', icon: IconArrowBackUp }];
      case 'rejected': return [
        { key: 'resubmit', label: 'Đăng ký lại', tone: 'primary', icon: IconRefresh },
        { key: 'edit', label: 'Sửa', tone: 'neutral', icon: IconPencil },
      ];
      case 'changeRequested': return [{ key: 'edit-submit', label: 'Chỉnh sửa & gửi lại', tone: 'primary', icon: IconPencil }];
      case 'approved': return [{ key: 'requestCancel', label: 'Yêu cầu hủy', tone: 'warning', icon: IconX }];
      default: return [];
    }
  }
  protected applyReg(r: ReqRow, key: string): void {
    switch (key) {
      case 'submit': case 'resubmit': case 'edit-submit': this.setStatus(r.id, 'pending'); break;
      case 'withdraw': this.setStatus(r.id, 'draft'); break;
      case 'requestCancel': this.setStatus(r.id, 'pendingCancel'); break;
      case 'edit': this.openEdit(r); break;
      case 'delete': this.rows.update((l) => l.filter((x) => x.id !== r.id)); this.peekOpen.set(false); break;
    }
  }

  // ── form ──
  protected readonly formMode = signal<'create' | 'edit'>('create');
  protected form = this.emptyForm();
  private emptyForm() { return { type: 'leave' as ReqTypeKey, from: '', to: '', approver: '', reason: '' }; }
  protected readonly typeOptions: HrmOption[] = (Object.keys(REQ_TYPES) as ReqTypeKey[]).map((k) => ({ value: k, label: REQ_TYPES[k] }));
  protected readonly approverOptions: HrmOption[] = [
    { value: 'Trần Văn Hùng', label: 'Trần Văn Hùng' }, { value: 'Vũ Đình Nam', label: 'Vũ Đình Nam' }, { value: 'Ngô Thị Lan', label: 'Ngô Thị Lan' },
  ];
  protected openCreate(): void { this.form = this.emptyForm(); this.formMode.set('create'); this.peekKind.set('form'); this.peekOpen.set(true); }
  protected openEdit(r: ReqRow): void {
    this.form = { type: r.type, from: r.from, to: r.to, approver: r.approver, reason: r.reason };
    this.selectedId.set(r.id); this.formMode.set('edit'); this.peekKind.set('form'); this.peekOpen.set(true);
  }
  /** Lưu bản nháp / gửi duyệt (demo: đóng peek). */
  protected saveDraft(): void { this.peekOpen.set(false); }
  protected saveForm(): void { this.peekOpen.set(false); }

  // ── table cols ──
  private readonly codeCell = viewChild<TemplateRef<any>>('codeCell');
  private readonly typeCell = viewChild<TemplateRef<any>>('typeCell');
  private readonly timeCell = viewChild<TemplateRef<any>>('timeCell');
  private readonly daysCell = viewChild<TemplateRef<any>>('daysCell');
  private readonly apprCell = viewChild<TemplateRef<any>>('apprCell');
  private readonly statusCell = viewChild<TemplateRef<any>>('statusCell');
  private readonly actionCell = viewChild<TemplateRef<any>>('actionCell');
  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'code', title: 'Mã đơn', width: '150px', cell: this.codeCell() },
    { key: 'type', title: 'Loại đơn', width: '150px', cell: this.typeCell() },
    { key: 'time', title: 'Thời gian', width: '190px', cell: this.timeCell() },
    { key: 'days', title: 'Số lượng', width: '110px', cell: this.daysCell() },
    { key: 'approver', title: 'Người duyệt', width: '150px', cell: this.apprCell() },
    { key: 'status', title: 'Trạng thái', width: '150px', cell: this.statusCell() },
    { key: 'act', title: '', align: 'right', width: '72px', fixed: 'right', cell: this.actionCell() },
  ]);
}
